CREATE TABLE IF NOT EXISTS ai_approvals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,ai_run_id UUID REFERENCES ai_runs(id) ON DELETE SET NULL,requested_by UUID REFERENCES users(id) ON DELETE SET NULL,reviewed_by UUID REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','expired')),reason TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),reviewed_at TIMESTAMPTZ);CREATE INDEX IF NOT EXISTS ai_approvals_tenant_idx ON ai_approvals(tenant_id,status,created_at DESC);